// Comb filter structure
struct CombFilter {
  float buffer[bufferSize];
  int bufferIndex = 0;
  float feedback = 0.84f;
  float damp1 = damping * 0.4f;  // damping coefficient
  float damp2 = 1.0f - damp1;
  float filterStore = 0.0f;

  float process(float input) {
    float output = buffer[bufferIndex];

    // One-pole damping filter
    filterStore = (output * damp2) + (filterStore * damp1);

    // Write to buffer with damped feedback
    buffer[bufferIndex] = input + (filterStore * feedback);

    bufferIndex = (bufferIndex + 1) % bufferSize;
    return output;
  }
};

// All-pass filter structure
struct AllPassFilter {
  float buffer[bufferSize];
  int bufferIndex = 0;
  float feedback = 0.5f;

  float process(float input) {
    float bufOut = buffer[bufferIndex];
    float output = -input + bufOut;

    buffer[bufferIndex] = input + (bufOut * feedback);

    bufferIndex = (bufferIndex + 1) % bufferSize;
    return output;
  }
};

// Process left and right independently
